//! Canonical structured claim registry.
//!
//! Human-facing text stays on `Claim`; evidence is deliberately typed so a
//! missing proof cannot be confused with proof that is not applicable.

use super::Status;

mod types;

pub use types::{Claim, ClaimEvidence, EvidenceState};

macro_rules! claim {
    (
        $id:literal, $name:literal, $status:expr, $note:expr, $instead:expr,
        impl: [$($implementation:literal),* $(,)?],
        tests: [$($test:literal),* $(,)?],
        local: $local:expr,
        external: $external:expr,
        next: $next:literal,
        owner: $owner:expr $(,)?
    ) => {
        Claim {
            id: $id,
            name: $name,
            status: $status,
            note: $note,
            instead: $instead,
            evidence: ClaimEvidence {
                implementation_refs: &[$($implementation),*],
                automated_test_refs: &[$($test),*],
                local_live: $local,
                external_required: $external,
            },
            next_action: $next,
            blocker_owner: $owner,
        }
    };
}

const SOURCE_PROOF: EvidenceState = EvidenceState::NotRequired(
    "the bounded source surface and deterministic automated gate are the required proof",
);
const NO_EXTERNAL_PROOF: EvidenceState =
    EvidenceState::NotRequired("the claim is bounded to local product behavior");
const POLICY_PROOF: EvidenceState = EvidenceState::NotRequired(
    "the refusal policy is proved by deterministic tests and has no live success path",
);

